import {escapeHTML} from './primitives.js?v=29';
import {itemPreview,pieceSVG} from '../pieces.js?v=29';
import {craftCost,itemById,PIECE_NAMES,rarityNames} from '../catalog.js?v=29';
import {dayLabel} from '../activity.js?v=29';
export const exportPgnDialog = (pgn) => `<h2>Экспорт партии</h2><p>Скачайте файл или скопируйте весь текст для анализа.</p><textarea id="pgn-text" class="pgn-text" aria-label="PGN партии" readonly>${escapeHTML(pgn)}</textarea><div class="actions"><button class="quiet" data-download-pgn>Скачать PGN</button><button class="quiet" data-copy-pgn>Скопировать PGN</button><button class="quiet" data-share-pgn>Поделиться</button></div>`;
export const cancelledDialog = () => '<h2>Партия отменена</h2><p>Вы не сделали ни одного хода. Партия не учитывается в статистике.</p>';
export const matchResultDialog = (title,reward,entry,breakdown) => `<p class="eyebrow">ПАРТИЯ ЗАВЕРШЕНА</p><h2>${escapeHTML(title)}</h2><p class="reward-total">+${reward} монет</p>${breakdown?`<dl class="reward-breakdown"><div><dt>Завершение партии</dt><dd>+${breakdown.completion}</dd></div><div><dt>Ваши ходы: ${breakdown.cleanMoves}<small>+1 за каждые 2 хода · максимум +20</small></dt><dd>+${breakdown.moves}</dd></div><div><dt>${breakdown.outcome==='win'?'Победа':breakdown.outcome==='draw'?'Ничья':'Поражение'}</dt><dd>+${breakdown.result}</dd></div></dl>${breakdown.reason==='early-resignation'?'<p class="reward-note">При сдаче раньше 10 ваших ходов монеты не начисляются.</p>':''}`:''}<p>Партия сохранена в истории профиля.</p>`;
export const botFailureDialog = () => '<h2>Компьютер не смог ответить</h2><p>Повторите расчёт или завершите партию без изменения прогресса. История ходов сохранится.</p><button class="quiet" data-retry-bot>Повторить расчёт</button><button class="quiet" data-export-pgn>Экспорт PGN</button><button class="quiet" data-abort-failed>Отменить партию</button>';
export const promotionDialog = (color,equipped) => `<h2>Превращение пешки</h2><p>Выберите фигуру</p><div class="promotion">${['q','r','b','n'].map(type=>`<button data-promote="${type}" aria-label="${PIECE_NAMES[type]}">${pieceSVG(type,color,itemById(equipped.pieces[type]).style)}</button>`).join('')}</div>`;
export const craftDialog = (item,id) => `<p class="eyebrow">МАСТЕРСКАЯ</p><div class="result-art">${itemPreview(item)}</div><h2>${item.name}</h2><p>Создать выбранный предмет за ${craftCost(item)} осколков? Случайности нет.</p><button class="primary" data-confirm-craft="${id}">Создать за ${craftCost(item)} ✧</button>`;
export const saveSetDialog = () => '<h2>Сохранить свой набор</h2><p>Сохраним шесть выбранных скинов и текущую доску.</p><form id="save-set-form"><label for="set-name">Название</label><input id="set-name" name="name" maxlength="32" required placeholder="Например, Полярная ночь" autocomplete="off"><button class="primary" type="submit">Сохранить набор</button></form>';
export const activityDialog = (event) => `<div class="day-closed-mark" aria-hidden="true">✓</div><h2>День закрыт</h2><p>${event.streak===1?'Началась новая серия.':`Вы играете ${dayLabel(event.streak)} подряд.`}</p><strong class="streak-value">${dayLabel(event.streak)}</strong>`;
export const chestRewardDialog = (title,artwork,item,shards,copy,duplicate) => `<p class="eyebrow">${title}</p><div class="result-art reveal">${artwork}</div>${item?`<span class="rarity ${item.rarity}">${rarityNames[item.rarity]}</span><h2>${item.name}</h2>`:''}${shards?`<h2>+${shards} осколков</h2>`:''}<p>${copy}</p>${item&&!duplicate?`<button class="quiet" data-use-reward="${item.id}">Использовать</button>`:''}`;
export const resignDialog = () => '<h2>Завершить партию?</h2><p>До вашего первого хода партия будет отменена. После первого хода завершение засчитается как поражение. Монеты за сдачу начисляются только после 10 ваших ходов.</p><button class="primary" data-confirm-resign>Завершить партию</button>';
export const installHelpDialog = () => '<h2>Установить GachaChess</h2><p>На iPhone: откройте сайт в Safari → «Поделиться» → «На экран Домой».</p><p>На Android и компьютере: в меню браузера выберите «Установить приложение».</p><p>После загрузки офлайн-кэша можно играть без интернета.</p>';
